CREATE OR ALTER PROCEDURE [dbo].[uspProductionPlan_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @ShiftId UNIQUEIDENTIFIER = NULL
	, @Status NVARCHAR(MAX) = NULL
	, @OrganizationUnitId UNIQUEIDENTIFIER = NULL
	, @PlanNumber NVARCHAR(MAX) = NULL
	, @PlanDate DATETIME2 = NULL
	, @Note NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[ProductionDate]
			, t.[ShiftId]
			, t.[Status]
			, t.[Note]
			, t.[PlanNumber]
			, t.[PlanDate]
			, t.[OrganizationUnitId]
			, t.[CreatedDate]
		FROM [dbo].[ProductionPlan] AS t
		
		WHERE (ISNULL(@SearchText, '') = '' OR t.[PlanNumber] LIKE CONCAT('%', @SearchText, '%'))
			AND (@ShiftId IS NULL OR t.[ShiftId] = @ShiftId)
			AND (ISNULL(@Status, '') = '' OR t.[Status] = @Status)
			AND (@OrganizationUnitId IS NULL OR t.[OrganizationUnitId] = @OrganizationUnitId)
			AND (ISNULL(@PlanNumber, '') = '' OR t.[PlanNumber] LIKE CONCAT('%', @PlanNumber, '%'))
			AND (@PlanDate IS NULL OR t.[PlanDate] = @PlanDate)
			AND (ISNULL(@Note, '') = '' OR t.[Note] LIKE CONCAT('%', @Note, '%'))
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'productionDate' THEN r.[ProductionDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'productionDate' THEN r.[ProductionDate] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'shiftId' THEN r.[ShiftId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'shiftId' THEN r.[ShiftId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'status' THEN r.[Status] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'status' THEN r.[Status] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'note' THEN r.[Note] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'note' THEN r.[Note] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'planNumber' THEN r.[PlanNumber] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'planNumber' THEN r.[PlanNumber] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'planDate' THEN r.[PlanDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'planDate' THEN r.[PlanDate] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'organizationUnitId' THEN r.[OrganizationUnitId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'organizationUnitId' THEN r.[OrganizationUnitId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
